import { View, type ViewProps, styled } from 'tamagui'
import {
  type BreakpointRange,
  type HideProps,
  type ShowProps,
  isEmptyRange,
  rangeSteps,
} from './range'

// Web: CSS media queries hide the content, so the server renders the right
// thing for every width (no flash, no hydration mismatch) and the content
// stays mounted. `display: contents` keeps the wrapper out of the layout:
// its children lay out as if they were the parent's own.
const Frame = styled(View, { name: 'ShowHide', display: 'contents' })

// Bundlers replace `process.env.NODE_ENV`; this types it for apps without Node's types.
declare const process: { env: { NODE_ENV?: string } }

let warned = false

function displayStyle(range: BreakpointRange, show: boolean): ViewProps {
  if (isEmptyRange(range)) {
    if (process.env.NODE_ENV !== 'production' && !warned) {
      warned = true
      console.warn('Show / Hide: `below` must be a larger breakpoint than `above`.')
    }
    return { display: show ? 'none' : 'contents' }
  }
  const style: Record<string, unknown> = {}
  for (const [key, inRange] of Object.entries(rangeSteps(range))) {
    const display = inRange === show ? 'contents' : 'none'
    if (key === 'base') style.display = display
    else style[`$${key}`] = { display }
  }
  return style as ViewProps
}

/** Renders its children only while the window is in the range: `above="md"` is md and up. */
export function Show({ children, ...range }: ShowProps) {
  return <Frame {...displayStyle(range as BreakpointRange, true)}>{children}</Frame>
}

/** Renders its children except while the window is in the range: `below="sm"` hides on phones. */
export function Hide({ children, ...range }: HideProps) {
  return <Frame {...displayStyle(range as BreakpointRange, false)}>{children}</Frame>
}

export type { BreakpointRange, HideProps, ShowProps } from './range'

import { useMedia } from 'tamagui'
import { type BreakpointRange, type HideProps, type ShowProps, isEmptyRange } from './range'

// Native has no CSS: read the window size and leave the hidden content out,
// so it is unmounted (and its state reset) while hidden.
function useInRange({ above, below }: BreakpointRange) {
  const media = useMedia()
  if (isEmptyRange({ above, below } as BreakpointRange)) return false
  return (!above || media[above]) && (!below || !media[below])
}

/** Renders its children only while the window is in the range: `above="md"` is md and up. */
export function Show({ children, ...range }: ShowProps) {
  return useInRange(range as BreakpointRange) ? <>{children}</> : null
}

/** Renders its children except while the window is in the range: `below="sm"` hides on phones. */
export function Hide({ children, ...range }: HideProps) {
  return useInRange(range as BreakpointRange) ? null : <>{children}</>
}

export type { BreakpointRange, HideProps, ShowProps } from './range'

import type { ReactNode } from 'react'
import { type Breakpoint, breakpointKeys } from '../../utils/responsive'

/** A width range: from `above` (inclusive) to `below` (exclusive). Give at least one. */
export type BreakpointRange =
  { above: Breakpoint; below?: Breakpoint } | { above?: Breakpoint; below: Breakpoint }

export type ShowProps = BreakpointRange & { children?: ReactNode }
export type HideProps = ShowProps

/**
 * Whether the window is in the range at each breakpoint it changes at:
 * `above="sm" below="lg"` is `{ base: false, sm: true, lg: false }`. Out of
 * range below `above`, in range from it, and out of range again from `below`.
 */
export function rangeSteps({ above, below }: BreakpointRange) {
  const steps: Partial<Record<'base' | Breakpoint, boolean>> = { base: !above }
  if (above) steps[above] = true
  if (below) steps[below] = false
  return steps
}

/** True when `below` is not above `above`, so nothing is ever in range. */
export function isEmptyRange({ above, below }: BreakpointRange) {
  return (
    above !== undefined &&
    below !== undefined &&
    breakpointKeys.indexOf(below) <= breakpointKeys.indexOf(above)
  )
}

import { getConfig, useDidFinishSSR, useMedia } from 'tamagui'
import {
  type Breakpoint,
  type Responsive,
  breakpointKeys,
  resolveResponsive,
} from '../utils/responsive'

/**
 * The largest min-width breakpoint the window matches, or `'base'` below `xs`.
 * It re-renders when that changes.
 *
 * The server can't know the width, so it renders for a phone (the config's
 * `mediaQueryDefaultActive`, `xs` here). Until hydration finishes the client
 * returns the same, so the markup matches and React logs no hydration error,
 * then it re-renders with the real breakpoint. Lay pages out with Show / Hide
 * or responsive props, which are CSS on web, and keep this for behavior.
 */
export function useBreakpoint(): 'base' | Breakpoint {
  const media = useMedia()
  const hydrated = useDidFinishSSR()
  const active: Record<string, boolean | undefined> = hydrated
    ? media
    : (getConfig().settings.mediaQueryDefaultActive ?? {})
  let current: 'base' | Breakpoint = 'base'
  for (const key of breakpointKeys) if (active[key]) current = key
  return current
}

/**
 * The value of a responsive prop at the current breakpoint, with the same
 * mobile-first cascade as the layout props: `{ base: 1, md: 3 }` is 1 below md
 * and 3 from md. `undefined` below the first breakpoint of a map without `base`.
 */
export function useBreakpointValue<T>(value: Responsive<T>): T | undefined {
  return resolveResponsive(value, useBreakpoint())
}

